,["arg2"]=[[开启神功系统]],["arg3"]=1,["id"]=[[rlt_digongquest05]]},["rlt_digongqzhr01"]={["arg1"]=[[换人]],["arg2"]=[[digongqz01_1]],["arg3"]=[[digongqz01_2]],["id"]=[[rlt_digongqzhr01]]},["rlt_digongqzhr02"]={["arg1"]=[[换人]],["arg2"]=[[digongqz02_1]],["arg3"]=[[fb02r25_1]],["id"]=[[rlt_digongqzhr02]]},["rlt_digongqzhr03"]={["arg1"]=[[换人]],["arg2"]=[[digongqz01_6]],["arg3"]=[[digongqz01_3]],["id"]=[[rlt_digongqzhr03]]},["rlt_digongqzhr04"]={["arg1"]=[[换人]],["arg2"]=[[digongqz01_3]],["arg3"]=[[digongqz01_4]],["id"]=[[rlt_digongqzhr04]]},["rlt_digongqzhr05"]={["arg1"]=[[换人]],["arg2"]=[[digongitem01]],["arg3"]=[[digongitem02]],["id"]=[[rlt_digongqzhr05]]},["rlt_digongqzhr06"]={["arg1"]=[[换人]],["arg2"]=[[fb02r25_1]],["arg3"]=[[digongqz02_1]],["id"]=[[rlt_digongqzhr06]]},["rlt_digongqzhr07"]={["arg1"]=[[换人]],["arg2"]=[[dgwp10a]],["arg3"]=[[dgwp10b]],["id"]=[[rlt_digongqzhr07]]},["rlt_digongqzhr08"]={["arg1"]=[[换人]],["arg2"]=[[digongitem03a]],["arg3"]=[[digongitem03]],["id"]=[[rlt_digongqzhr08]]},["rlt_digongqzhr10"]={["arg1"]=[[换人]],["arg2"]=[[digongqz01_2]],["arg3"]=[[digongqz01_6]],["id"]=[[rlt_digongqzhr10]]},["rlt_digongqzhr11"]={["arg1"]=[[换人]],["arg2"]=[[digongitem01]],["arg3"]=[[digongitem02a]],["id"]=[[rlt_digongqzhr11]]},["rlt_digongqztext1"]={["arg1"]=[[副本故事]],["arg2"]=[[YEL神秘老者：老朽眼睛不能视物，登山时不慎从栈道上摔下来弄伤了腿。随行弟子前去找药，几个时辰都未回来。;YEL神秘老者：山下松林小道上似乎有人采药，少侠可否前去替老朽讨些治伤之药回来？NOR]],["arg3"]=[[1;1]],["id"]=[[rlt_digongqztext1]]},["rlt_digongqztext10"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL程墟：多谢少侠相助。这枚堪舆符是我师门信物，还请少侠前往扬州城杂货铺，将此信物交予我师兄，他定有重礼酬谢少侠。]],["id"]=[[rlt_digongqztext10]]},["rlt_digongqztext11"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL神秘老者：老朽和劣徒有伤在身，不便多留。少侠，咱们就此别过。]],["id"]=[[rlt_digongqztext11]]},["rlt_digongqztext12"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL程墟：多谢少侠相助，程墟铭感五内。]],["id"]=[[rlt_digongqztext12]]},["rlt_digongqztext13"]={["arg1"]=[[副本故事]],["arg2"]=[[YEL神秘老者：老朽年轻时以盗墓为生，座下弟子称我为堪舆老人。我来此地，是为了探查一座大墓地宫。;YEL神秘老者：这地宫内藏着一些高深武学的秘密，更可能藏着老朽一位故人的下落。老朽已派一位徒儿潜入墓中，至今音信全无，料想已是凶多吉少。NOR;YEL神秘老者：老朽感觉少侠是个值得信赖之人，想拜托少侠替老朽下一趟地宫，将我徒儿救出。;YEL神秘老者：那地宫入口就在南岭山脉附近，少侠可凭此图打开地宫大门，老朽腿伤眼盲，只好留在此地，静候少侠佳音。NOR]],["arg3"]=[[1.5;1.5;1.5;1.5]],["id"]=[[rlt_digongqztext13]]},["rlt_digongqztext2"]={["arg1"]=[[副本故事]],["arg2"]=[[你将老者受伤之事告诉采药人，并希望他能给一些治伤之药。;YEL采药人：山上的栈道年久失修，十分容易跌落。三七有止血定痛之效，我这刚好有用三七粉配成的伤药，你去拿给那位老人家吧。NOR]],["arg3"]=[[1;1]],["id"]=[[rlt_digongqztext2]]},["rlt_digongqztext3"]={["arg1"]=[[文本输出]],["arg2"]=[[老者接过药粉洒在伤口上，片刻后老者的脸上恢复了血色。他喊你过去，示意还有话想对你说。]],["id"]=[[rlt_digongqztext3]]},["rlt_digongqztext4"]={["arg1"]=[[副本故事]],["arg2"]=[[YEL神秘老者：老朽年轻时以盗墓为生，座下弟子称我为堪舆老人。我来此地，是为了探查一座大墓地宫。;YEL神秘老者：这地宫内藏着一些高深武学的秘密，更可能藏着老朽一位故人的下落。老朽已派一位徒儿潜入墓中，至今音信全无，料想已是凶多吉少。NOR;YEL神秘老者：老朽感觉少侠是个值得信赖之人，想拜托少侠替老朽下一趟地宫，将我徒儿救出。那地宫入口就在南岭山脉附近，老朽腿伤眼盲，只好留在此地，静候少侠佳音。NOR]],["arg3"]=[[1.5;1.5;1]],["id"]=[[rlt_digongqztext4]]},["rlt_digongqztext5"]={["arg1"]=[[文本输出]],["arg2"]=[[你看到路边坐着一位老者。老者的眼睛被缎带蒙上，脸色铁青，裤子被染红，似乎受了不轻的伤。他听见你的脚步声，连忙喊你过去。]],["id"]=[[rlt_digongqztext5]]},["rlt_digongqztext6"]={["arg1"]=[[文本输出]],["arg2"]=[[这是一面异常平滑的岩壁，你仔细观察了一遍，发现岩壁中央有一扇石门。]],["id"]=[[rlt_digongqztext6]]},["rlt_digongqztext7"]={["arg1"]=[[文本输出]],["arg2"]=[[你进入了石门，穿过一段狭窄的缝隙后，竟发现里面别有洞天。]],["id"]=[[rlt_digongqztext7]]},["rlt_digongqztext8"]={["arg1"]=[[文本输出]],["arg2"]=[[无论你如何仔细的寻找，却怎么也找不到此前发现的石门。]],["id"]=[[rlt_digongqztext8]]},["rlt_digongqztext9"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL神秘老者：老朽已在这盗洞口等候多时，可算是把你们等出来了。]],["id"]=[[rlt_digongqztext9]]},["rlt_digongtextout01"]={["arg1"]=[[弹出文本]],["arg2"]=[[进入地宫]],["id"]=[[rlt_digongtextout01]]},["rlt_digongtextout02"]={["arg1"]=[[弹出文本]],["arg2"]=[[你的等级不足。]],["id"]=[[rlt_digongtextout02]]},["rlt_digongtextout03"]={["arg1"]=[[弹出文本]],["arg2"]=[[你的传承次数不足。]],["id"]=[[rlt_digongtextout03]]},["rlt_digongtextout04"]={["arg1"]=[[弹出文本]],["arg2"]=[[你获得了  堪舆符]],["id"]=[[rlt_digongtextout04]]},["rlt_digongtextout05"]={["arg1"]=[[弹出文本]],["arg2"]=[[你身上没有堪舆图，竟拿此石门毫无办法。]],["id"]=[[rlt_digongtextout05]]},["rlt_digongtp01"]={["arg1"]=[[副本无动画跳转]],["arg2"]=[[fb220]],["arg3"]=[[fb220_34]],["arg6"]=100,["id"]=[[rlt_digongtp01]]},["